/** "This video's length could not be read.": In the Trim video screen of the New Post composer: why the video can't be trimmed (the phone couldn't tell how long it is). */
fun S.appSocialTrimNoLength(): UiText =
    UiText.Res(R.string.app_social_trim_no_length)

/** "Reading the clip…": Beside a spinner in the Trim video screen of the New Post composer, while the video is being opened. */
fun S.appSocialTrimReading(): UiText =
    UiText.Res(R.string.app_social_trim_reading)

/** "Remove trim": Button of the Trim video screen (New Post composer), shown when the video was trimmed before: posts the whole video again. */
fun S.appSocialTrimRemove(): UiText =
    UiText.Res(R.string.app_social_trim_remove)

/** "Trim video": Title of the screen of the New Post composer where you choose the part of a video that goes into the post (Cancel and Apply in its bar). */
fun S.appSocialTrimTitle(): UiText =
    UiText.Res(R.string.app_social_trim_title)
